export const BODY: string = "\n<p>كولاج الصور يحوّل عدة صور إلى صورة واحدة: يعرض مجموعة لحظات معًا، رحلة أو تشكيلة منتجات أو قبل وبعد أو لقاءً عائليًا. والكولاج يقول أكثر من صف صور.</p>\n<p>منشئ كولاج الصور يرتب صورك في شبكات 2 في 2 و3 في 3 أو في أشرطة عمودية وأفقية، مع السحب للتبديل وتقسيمات قابلة للضبط وفراغات وزوايا مدورة وتصدير حتى 4000 بكسل.</p>\n<p>يشرح هذا الدليل التخطيطات وضوابط الترتيب وخيارات التأطير وخيارات التصدير، ويُظهر أي تخطيط يناسب كل مهمة: سواء صنعت منشورًا اجتماعيًا أو طباعة أو ملخصًا.</p>\n<h2 id=\"what-is-a-collage-maker\">ما منشئ الكولاج؟</h2>\n<p>منشئ الكولاج يرتب عدة صور في صورة واحدة على لوحة مشتركة: كل صورة تبقى في خلية، والخلايا معًا تشكل شبكة أو شريطًا. والنتيجة ملف واحد تستطيع نشره أو طباعته أو إرساله.</p>\n<p>الأداة مختلفة عن محرر صور: لا تغيّر الصور نفسها، بل ترتبها. وتختار التخطيط وتضع الصور وتضبط التباعد وتصدّر الصورة المدمجة كـJPG أو PNG.</p>\n<p>تُستخدم الكولاجات لمنشورات اجتماعية، حيث صورة واحدة تحمل لحظات عدة؛ ولإعلانات منتج، حيث صورة واحدة تُظهر تشكيلة؛ ولمقارنات قبل وبعد، حيث صورتان جنبًا إلى جنب ترويان قصة.</p>\n<p>ويعمل منشئ الكولاج في المتصفح، فصورك لا تغادر جهازك أبدًا: ذلك مهم لصور عائلية وصور قبل وبعد لعملاء، وهي خاصة بطبيعتها.</p>\n<h2 id=\"layouts-grids-and-strips\">التخطيطات: شبكات وأشرطة</h2>\n<p>توفر الأداة تخطيطي شبكة وتخطيطي شريط: شبكة 2 في 2 تحمل أربع صور في مربع، وشبكة 3 في 3 تحمل تسعًا. والشريط العمودي يكدّس صورًا في عمود، والأفقي يرتبها في صف.</p>\n<p>يُختار التخطيط تلقائيًا حسب عدد الصور التي ترفعها: رفع خمس صور أو أكثر يختار شبكة 3 في 3، بينما أربع أو أقل يختار شبكة 2 في 2. وتستطيع تغيير التخطيط في أي وقت بعد الرفع.</p>\n<p>الشبكات تناسب مجموعات صور تنتمي معًا: رحلة أو حدث أو تشكيلة منتجات. والشكل المربع يناسب الخلاصات والإعلانات والمصغرات، والخلايا المتساوية تعطي كل صورة وزنًا متساويًا.</p>\n<p>الأشرطة تناسب تسلسلات ومقارنات: شريط عمودي يُقرأ من أعلى إلى أسفل كقصة، ما يناسب يومًا مرتبًا أو عملية خطوة بخطوة. وشريط أفقي يُقرأ من يسار إلى يمين كخط زمني، ما يناسب قبل وبعد أو بانوراما لحظات.</p>\n<h2 id=\"uploading-photos\">كيف ترفع صورًا</h2>\n<p>اسحب صورك إلى منطقة الرفع، أو انقر لاختيارها من جهازك: تقبل الأداة ملفات JPG وPNG وWebP وHEIC وGIF وBMP وSVG حتى 20 MB لكل ملف، فصور الهواتف بدقة كاملة تناسب بسهولة.</p>\n<p>رفع مزيج من الصيغ يعمل جيدًا: صورة HEIC من آيفون ولقطة PNG وJPG من كاميرا قد تبقى في نفس الكولاج، لأن الأداة تحوّل كلًا منها للعرض والتصدير. ويحدد عدد الصور التخطيط الأولي: خمس صور أو أكثر تختار تلقائيًا شبكة 3 في 3، وأربع أو أقل تختار تلقائيًا شبكة 2 في 2. وإذا رفعت صورًا أقل من خلايا التخطيط، تبقى الخلايا الفارغة فارغة حتى تضيف المزيد.</p>\n<p>اختر صورًا بجودة وإضاءة متشابهة عندما تستطيع: كولاج من تسع صور حيث واحدة داكنة وضبابية يجذب العين إلى الصورة الضعيفة، بينما مجموعة بإضاءة متسقة تبدو كوحدة واحدة.</p>\n<h2 id=\"drag-swap-and-tap-swap\">السحب للتبديل والنقر للتبديل</h2>\n<p>ترتيب الصور عمل سحب وإفلات على الحاسوب: تأخذ صورة وتسقطها على خلية أخرى، وتتبادل الصورتان مكانيهما. والتبديل فوري، وتستطيع إعادة الترتيب بقدر ما تريد قبل التصدير.</p>\n<p>على هاتف أو جهاز لوحي، النقر للتبديل يقوم بنفس العمل: انقر صورة لاختيارها، ثم انقر الخلية التي تريد نقلها إليها، وتتبادل الصورتان مكانيهما. والسحب على شاشة لمس صغير محبط، فالنقر للتبديل هو الطريقة الموثوقة هناك.</p>\n<p>الترتيب مهم لأن العين تقرأ كولاجًا بترتيب: الخلية العلوية اليسرى تُرى أولًا، والخلية المركزية تجذب العين في شبكة 3 في 3، والخلية السفلية اليمنى تُرى أخيرًا.</p>\n<p>جرّب ترتيبات عدة قبل أن تقرر: صورة تبدو ضائعة في خلية قد تثبّت الكولاج في أخرى، وتبديل يستغرق ثانية قد يغيّر التوازن كله. والمعاينة المباشرة تُظهر كل تبديل فورًا.</p>\n<h2 id=\"adjusting-splits\">كيف تضبط التقسيمات</h2>\n<p>التقسيمات هي الخطوط بين الخلايا، ويمكن ضبطها: اسحب خط تقسيم لتجعل خلية أكبر وجارتها أصغر، ما يتيح لصورة مميزة أن تشغل مساحة أكبر.</p>\n<p>الصورة المميزة هي سبب ضبط تقسيم: صورة رئيسية للشخص الرئيسي تستحق خلية أكبر، بينما صور الدعم قد تكون أصغر. وشبكة بلا صورة مميزة تعطي كل صورة وزنًا متساويًا، ما يناسب مجموعة حيث كل لقطة مهمة بالتساوي.</p>\n<p>وإذا أصبحت التقسيمات غير متساوية وأردت البدء من جديد، أعدها إلى شبكة موحدة: تعيد الأداة التقسيمات إلى خلايا متساوية، فتستطيع تجربة ترتيب آخر دون إعادة رفع أي شيء.</p>\n<p>أبقِ التقسيمات معقولة: خلية مضغوطة حتى تصبح شريطًا رفيعًا تقص كثيرًا من صورتها، وخلية مكبرة أكثر مما يلزم تخل بتوازن الشبكة. والضبطات الصغيرة تحسّن كولاجًا، بينما الضبطات الكبيرة تكسره.</p>\n<h2 id=\"gaps-and-rounded-corners\">الفراغات والزوايا المدورة</h2>\n<p>الفراغ هو الفصل بين الخلايا، ويحدد إحساس الكولاج: فراغ صفر يعطي كولاجًا متصلًا بلا حدود، حيث الصور تتلامس وتشكل صورة واحدة مستمرة. وفراغ واسع يعطي كل صورة مساحتها الخاصة، ما يجعل الكولاج يبدو كلوحة معرض.</p>\n<p>تباعد الخلايا ونصف قطر الزاوية ضابطان مستقلان، فتستطيع تعيين فراغ واسع بزوايا مربعة، أو فراغ ضيق بزوايا مدورة. والمزيج الذي تختاره يحدد مزاج الكولاج.</p>\n<p>الزوايا المدورة تلطّف الكولاج وتناسب منشورات اجتماعية ورسومًا بأسلوب تطبيق: والزوايا المربعة تبدو رسمية وتناسب مطبوعات وإعلانات منتج.</p>\n<p>ولون الخلفية يظهر من خلال الفراغات، فالفراغ والخلفية يعملان معًا: فراغ أبيض على خلفية بيضاء يبدو كحد نظيف، بينما لون علامة في الفراغات يربط الكولاج بحملة.</p>\n<h2 id=\"image-fit-cover-vs-contain\">ملاءمة الصورة: تغطية مقابل احتواء</h2>\n<p>ملاءمة الصورة تقرر ما يحدث عندما لا تطابق صورة شكل خليتها: \"تغطية\" تملأ الخلية تمامًا بقص الصورة، فلا مناطق فارغة لكن الحواف قد تُقص. و\"احتواء\" يلائم الصورة كلها داخل الخلية دون قص، فلا يُفقد شيء لكن يظهر فراغ حول الصورة.</p>\n<p>\"تغطية\" هو الافتراضي ويناسب معظم الكولاجات: يملأ كل خلية ويجعل الشبكة تبدو مصقولة. و\"احتواء\" يناسب صورًا حيث كل تفصيلة مهمة، مثل وثيقة أو منتج بملصق.</p>\n<p>بدّل إلى \"احتواء\" عندما تقص \"تغطية\" شيئًا مهمًا: وجه على حافة صورة أو ملصق منتج أو سطر نص قد يُقص بتغطية، واحتواء ينقذها على حساب بعض الفراغ.</p>\n<p>راجع كل خلية بعد اختيار الملاءمة: كولاج يمزج صورًا عمودية وأفقية، والملاءمة التي تناسب خلية قد لا تناسب أخرى. وتُطبق الملاءمة لكل خلية، فتستطيع مزج تغطية واحتواء في نفس الكولاج.</p>\n<h2 id=\"background-colors\">ألوان الخلفية</h2>\n<p>لون الخلفية يملأ اللوحة خلف الصور ويظهر من خلال الفراغات: توفر الأداة ألوانًا سريعة مسبقة، فتستطيع اختيار أبيض نظيف أو محايد ناعم أو لون علامة.</p>\n<p>الأبيض هو الافتراضي والخيار الأكثر أمانًا: يبقي الكولاج نظيفًا ويمتزج مع أي خلاصة أو صفحة، ويجعل الصور اللون الوحيد في الصورة. ولن يتعارض خلفية بيضاء أبدًا مع صورة.</p>\n<p>لون علامة يحوّل الكولاج إلى رسم مصمم: اللون في الفراغات يوحد الكولاج مع حملة، ومجموعة كولاجات بنفس اللون تشكل سلسلة مميزة. واستخدمه عندما يكون اللون جزءًا من هويتك.</p>\n<p>ملصقات PNG شفافة موضوعة في خلايا تُظهر لون الخلفية خلفها: ملصق على خلفية بيضاء يُقرأ كقص نظيف، بينما ملصق على خلفية ملونة يبدو جزءًا من التصميم.</p>\n<h2 id=\"canvas-sizes-and-ratios\">أحجام اللوحة ونسبها</h2>\n<p>حجم اللوحة ونسبتها يقرران الشكل النهائي للكولاج: توفر الأداة أبعاد لوحة سريعة ونسبًا مسبقة، فتستطيع بناء مربع للخلاصة أو عمودي للقصة أو واسع للافتة.</p>\n<p>المربع هو الشكل الأكثر تنوعًا: يعمل في خلاصات وإعلانات ومصغرات، ويُقص بشكل متوقع في كل مكان. وكولاج مربع بشبكة 2 في 2 أو 3 في 3 هو الخيار الأكثر أمانًا لمعظم الاستخدامات.</p>\n<p>النسب العمودية تناسب قصصًا وخلفيات هاتف، حيث تُرى الصورة طويلة: شريط عمودي على لوحة عمودية يُقرأ كقصة تروى من أعلى إلى أسفل.</p>\n<p>والنسب الواسعة تناسب لافتات وترويسات، حيث يجلس الكولاج أعلى صفحة: شريط أفقي على لوحة واسعة يُقرأ من يسار إلى يمين كخط زمني.</p>\n<h2 id=\"feature-photos\">صور مميزة</h2>\n<p>الصورة المميزة صورة جُعلت أكبر من البقية، وهي أبسط طريقة لمنح كولاج نقطة تركيز: تصل العين إلى الصورة الكبيرة أولًا، ثم تستكشف الأصغر.</p>\n<p>اجعل أقوى صورة هي المميزة: الصورة الرئيسية لرحلة أو أفضل زاوية منتج أو الصورة الشخصية الرئيسية تستحق الخلية الكبيرة. وصورة ضعيفة مكبرة تجذب الانتباه فقط إلى ضعفها.</p>\n<p>اضبط التقسيمات لتكبير الخلية المميزة، أو اختر تخطيطًا يفضل خلية أصلًا: شبكة 2 في 2 بخلية مكبرة تُقرأ كعرض، بينما شبكة 3 في 3 بخلية مركزية مكبرة تُقرأ كقطعة مركزية.</p>\n<p>أبقِ المميزة صورة واحدة: خليتان كبيرتان تتنافسان معًا وينكسر التسلسل. ومميزة واحدة، أكبر بوضوح من البقية، هي القاعدة التي تجعل الكولاج يُقرأ في لمحة.</p>\n<h2 id=\"export-jpg-vs-png\">تصدير JPG مقابل PNG</h2>\n<p>تصدّر الأداة الكولاج النهائي كـJPG أو PNG: JPG يناسب صورًا وأي كولاج حيث حجم ملف صغير مهم، مثل منشور اجتماعي أو صورة موقع.</p>\n<p>PNG يناسب كولاجات بنص حاد أو ألوان مسطحة أو شفافية يجب أن تنجو: ملف PNG أكبر، لكنه يحافظ على كل حافة محددة ويحفظ المناطق الشفافة بكاملها.</p>\n<p>دقة التصدير تصل إلى 4000 بكسل، كبيرة بما يكفي للطباعة: كولاج مصدر إلى 4000 بكسل يُطبع نظيفًا بحجم كبير، بينما تصدير صغير يُطبع ضبابيًا.</p>\n<p>واسم الملف المصدر يعكس ضبط الكولاج، فتستطيع تمييز النسخ عندما تصدّر عدة: اسم ملف واضح يوفر عليك فتح خمسة ملفات شبه متطابقة.</p>\n<h2 id=\"common-mistakes\">أخطاء شائعة</h2>\n<p>أكثر خطأ شيوعًا صور كثيرة جدًا: شبكة 3 في 3 بتسع صور مزدحمة صعبة القراءة، لأن لا صورة تحصل على مساحة كافية. وصور أقوى أقل تعطي كولاجًا أفضل.</p>\n<p>خطأ آخر تجاهل الملاءمة: صورة عمودية في خلية أفقية بتغطية تفقد أعلاها وأسفلها، ما قد يقطع وجهًا أو شخصًا. وراجع كل خلية بعد وضع الصور. وخطأ ثالث لون فراغ يتعارض مع الصور: لون فراغ ساطع بين صور باهتة يجذب العين إلى الفراغات بدل الصور، ولون فراغ داكن قد يجعل كولاجًا ساطعًا يبدو ثقيلًا.</p>\n<p>وأخيرًا، كثير من الناس يصدّرون بحجم صغير ثم يحاولون طباعة الكولاج: كولاج مصدر لوسائل التواصل الاجتماعي يُطبع سيئًا بحجم كبير، لأن البكسلات ليست موجودة. وصدّر بأكبر حجم قد تحتاجه.</p>\n<h2 id=\"quick-reference\">مرجع سريع: قائمة تحقق للكولاج</h2>\n<p>اختر أربع إلى تسع صور قوية بإضاءة متشابهة، وارفعها واترك التخطيط يختار الشبكة تلقائيًا. ورتب الصور بالسحب أو النقر للتبديل، وكبّر الصورة المميزة، واضبط التقسيمات والفراغات.</p>\n<p>اختر نسبة لوحة للوجهة، واختر JPG للصور وPNG للرسوم، وصدّر حتى 4000 بكسل للطباعة. وراجع كل خلية لقص سيئ قبل التنزيل.</p>\n<p>للإنشاء خطوة بخطوة، اقرأ <a href=\"/ar/blog/kayfiyya-ins-ha-kulaj-suwar/\">كيف تصنع كولاج صور</a>، ولأفكار التصميم اقرأ <a href=\"/ar/blog/takhtitat-kulaj-wa-shabakat-wa-lawhat-mizaj/\">تخطيطات كولاج: شبكات ولوحات مزاج وقصص</a>. واصنع كولاجك بـ<a href=\"/ar/munshi-kulaj-as-suwar/\">منشئ كولاج الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما الفرق بين كولاج وتقسيم شبكة؟","answer":"تقسيم الشبكة يقسم صورة إلى بلاطات تعيد بناء الأصل عندما توضع معًا: وكولاج يجمع عدة صور مختلفة في صورة واحدة. والتقسيم يقطع صورة إلى أجزاء، بينما الكولاج يوحد صورًا كثيرة في واحدة."},{"question":"كم صورة أستطيع وضعها في كولاج؟","answer":"الشبكات تحمل أربع صور في تخطيط 2 في 2 أو تسعًا في تخطيط 3 في 3، والأشرطة قد تحمل كثيرًا أكثر في صف أو عمود واحد. وأربع إلى تسع صور هي النطاق العملي؛ وأكثر من ذلك يجعل الكولاج صعب القراءة."},{"question":"هل أستطيع مزج صور عمودية وأفقية في كولاج؟","answer":"نعم، ملاءمة الصورة تتعامل مع المزيج: \"تغطية\" تملأ كل خلية بالقص، بينما \"احتواء\" تُظهر الصورة كلها بحد. وراجع كل خلية بعد وضع الصور، لأن الملاءمة التي تناسب خلية قد لا تناسب أخرى."},{"question":"أي حجم تصدير يجب أن أختار لكولاج؟","answer":"طابق الحجم مع الوجهة: منشورات اجتماعية تحتاج حجمًا معتدلًا فقط، بينما المطبوعات تحتاج أكبر تصدير، حتى 4000 بكسل. وصدّر بأكبر حجم قد تحتاجه، لأن تصغير صورة كبيرة سهل وإعادة تكبير صورة صغيرة مستحيلة."},{"question":"هل الكولاجات تعمل للطباعة؟","answer":"نعم، ما دمت تصدّر بدقة عالية: كولاج مصدر حتى 4000 بكسل يُطبع نظيفًا بحجم كبير. وصدّر كـPNG لأوضح طباعة، أو كـJPG عالي الجودة لطباعة فوتوغرافية."},{"question":"هل أستطيع تعديل كولاج بعد تصديره؟","answer":"ليس بسهولة، لأن التصدير صورة واحدة مسطحة: أبقِ الكولاج مفتوحًا في الأداة أثناء العمل، أو احفظ صور المصدر لإعادة بنائه. وإعادة البناء من الأصول أسرع من محاولة تعديل الملف المسطح."}];
